"""The event date rules against goldens generated by the OLD ``domain/events.py`` (review 014):
``python -m projectzero.ops.parity_events goldens``."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from projectzero.ops.parity_events import CLOCKS, corpus, differences, importer_differences, new_results, spans

GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_events_when.json").read_text(
        encoding="utf-8"
    )
)


def test_provenance_is_the_clean_old_revision_with_a_tz_database() -> None:
    assert GOLDEN["provenance"] == {
        "old_revision": "6c739b9cb6ca2517b845e381d39a36c50eccc59e",
        "old_dirty": False,
        "berlin": "zoneinfo.ZoneInfo(key='Europe/Berlin')",
    }


def test_the_golden_input_is_the_current_corpus() -> None:
    assert GOLDEN["values"] == json.loads(json.dumps(corpus()))
    assert GOLDEN["spans"] == json.loads(json.dumps(spans()))
    assert sorted(GOLDEN["clocks"]) == CLOCKS


@pytest.mark.parametrize("clock", CLOCKS)
def test_the_port_matches_the_old_code(clock: str) -> None:
    assert differences({clock: GOLDEN["clocks"][clock]}, GOLDEN["values"], GOLDEN["spans"]) == {clock: []}


@pytest.mark.parametrize("clock", CLOCKS)
def test_the_importer_span_is_the_old_event_span_wherever_the_old_code_did_not_raise(clock: str) -> None:
    assert importer_differences(GOLDEN["clocks"][clock]["event_span"], GOLDEN["spans"], clock) == []


def test_the_goldens_cover_the_rules() -> None:
    late = dict(zip(map(repr, GOLDEN["values"]), GOLDEN["clocks"]["2026-11-11"]["parse_when"], strict=True))
    early = dict(zip(map(repr, GOLDEN["values"]), GOLDEN["clocks"]["2026-03-15"]["parse_when"], strict=True))
    assert late["'2026-09-20'"] == {"ok": ["2026-09-20", "", ""]}  # a date stays a calendar date
    assert late["'2026-09-20T18:30:45'"] == {"ok": ["2026-09-20", "18:30", "Europe/Berlin"]}  # naive: Berlin, no secs
    assert late["'2026-09-19T23:30Z'"] == {"ok": ["2026-09-20", "01:30", "converted to Europe/Berlin"]}
    assert late["'20.09.26 18:30'"] == {"ok": ["2026-09-20", "18:30", "Europe/Berlin"]}
    assert late["'Sept 20'"] == {"ok": ["2027-09-20", "", ""]}  # a passed month without a year rolls over ...
    assert early["'Sept 20'"] == {"ok": ["2026-09-20", "", ""]}  # ... which is why the clock is a parameter
    assert late["'2026-09-20T24:00'"] == {"ok": ["2026-09-20", "24:00", "Europe/Berlin"]}  # kept; event_span raises
    assert late["'2026-09-20T18:30+99:00'"] == {"raises": "ValueError"}
    assert late["20260920"] == {"raises": "AttributeError"}  # not text: the old code raises
    spans_late = GOLDEN["clocks"]["2026-11-11"]["event_span"]
    assert spans_late[0] == {"ok": ["2026-09-20T00:00:00+02:00", "2026-09-21T00:00:00+02:00"]}  # exclusive end


def test_new_results_never_depend_on_the_machine_clock() -> None:
    one = new_results(["Sept 20"], [], "2026-03-15")["parse_when"]
    two = new_results(["Sept 20"], [], "2026-11-11")["parse_when"]
    assert one != two
